Office.context.document.settings.set("Office.AutoShowTaskpaneWithContext", true);
Office.context.document.settings.saveAsync();
const affUrl = "assets/mn_MN.aff";
const dicUrl = "assets/mn_MN.dic";
let spellChecker;
let lastMisspellings = new Map();
/** Сүүлийн шалгалтаас шинэ гарсан алдаат үгс — жагсаалтын дээд талд харуулна */
let lastNewWords = new Set();
/** Сүүлийн шалгалтын алдаат үгсийн документ дахь дараалал (сүүлд орсон нь эхэнд) */
let lastMisspellingOrder = [];
/** Үг бүрийн документ дахь сүүлд гарсан индекс (сүүлд бичсэн нь дээр) */
let lastOccurrenceIndex = new Map();
/** Карт бүрт сонгосон санал: word -> suggestion */
let selectedSuggestionByWord = new Map();
/** Татгалзсан үгс — жагсаалтаас хасагдана */
let ignoredWords = new Set();
let statusClearTimer = null;
/** Текст өөрчлөгдсөн эсэхийг шалгахын тулд сүүлд уншсан биеийн текст */
let lastBodyText = "";
/** Текст өөрчлөгдөх эсэхийг шалгах интервал (зөвхөн текст унших, өөрчлөгдсөн үед л бүтэн шалгалт) */
const TEXT_CHECK_INTERVAL_MS = 800;
const STATUS_CLEAR_AFTER_MS = 5000;

/** ⚡ Spell cache: үг -> { correct, suggestions? } — Hunspell дахин дуудахгүй */
const spellCache = new Map();
/** Unicode үгийн regex: зөвхөн үсэг (монгол, кирилл г.м) */
const WORD_REGEX = /[\p{L}\p{M}]+/gu;
/** Зөвхөн латин үсэг (англи үг) — шалгахгүй */
const LATIN_ONLY_REGEX = /^[a-zA-Z]+$/;

const STATUS_ICONS = {
  ready: '<i class="fa-solid fa-circle-check" aria-hidden="true"></i>',
  loading: '<i class="fa-solid fa-spinner" aria-hidden="true"></i>',
  success: '<i class="fa-solid fa-circle-check" aria-hidden="true"></i>',
  error: '<i class="fa-solid fa-circle-exclamation" aria-hidden="true"></i>',
};

function setStatusIcon(state) {
  const el = document.getElementById("status-icon");
  if (!el) return;
  el.className = "mn-header__status mn-header__status--" + state;
  el.innerHTML = STATUS_ICONS[state] || STATUS_ICONS.ready;
  const titles = { ready: "Бэлэн", loading: "Шалгаж байна", success: "Амжилттай", error: "Алдаа" };
  el.title = titles[state] || titles.ready;
  el.setAttribute("aria-label", titles[state] || titles.ready);
}

function setStatus(text) {
  if (statusClearTimer) {
    clearTimeout(statusClearTimer);
    statusClearTimer = null;
  }
  const el = document.getElementById("status");
  if (el) el.innerText = text;
}

function setStatusThenClear(text) {
  setStatus(text);
  statusClearTimer = setTimeout(() => {
    setStatus("");
    statusClearTimer = null;
  }, STATUS_CLEAR_AFTER_MS);
}

function getSelectedSuggestion(word, suggestions) {
  const list = suggestions || [];
  return selectedSuggestionByWord.get(word) ?? list[0] ?? null;
}

/** Англи (латин) үг эсэхийг шалгана — ийм үгийг алдаа шалгахгүй */
function isLatinOnly(word) {
  return LATIN_ONLY_REGEX.test(word);
}

/** ⚡ Кэшээс унших эсвэл Hunspell дуудаад кэшлэх. Буцах: { correct, suggestions? } */
function checkWord(word) {
  const cached = spellCache.get(word);
  if (cached !== undefined) return cached;
  const correct = spellChecker.spell(word);
  const entry = correct
    ? { correct: true }
    : { correct: false, suggestions: spellChecker.suggest(word) };
  spellCache.set(word, entry);
  return entry;
}

function renderSuggestions(misspellingsMap) {
  const container = document.getElementById("suggestions");
  const empty = document.getElementById("suggestions-empty");
  if (!container || !empty) return;

  container.innerHTML = "";
  let entries = Array.from(misspellingsMap.entries()).filter(([word]) => !ignoredWords.has(word));
  entries = entries.sort(([a], [b]) => {
    const aNew = lastNewWords.has(a);
    const bNew = lastNewWords.has(b);
    if (aNew && !bNew) return -1;
    if (!aNew && bNew) return 1;
    const i = lastMisspellingOrder.indexOf(a);
    const j = lastMisspellingOrder.indexOf(b);
    if (i === -1 && j === -1) return 0;
    if (i === -1) return 1;
    if (j === -1) return -1;
    return i - j;
  });

  if (entries.length === 0) {
    empty.style.display = "block";
    return;
  }

  empty.style.display = "none";

  for (const [word, suggestions] of entries) {
    const topSuggestions = (suggestions || []).slice(0, 8);
    const selected = getSelectedSuggestion(word, topSuggestions);

    const card = document.createElement("div");
    card.className = "spelling-card";

    const header = document.createElement("div");
    header.className = "spelling-card__header";
    header.innerHTML = `
      <span class="spelling-card__indicator"></span>
      <span class="spelling-card__title">Алдаатай үг</span>
      <span class="spelling-card__icon" aria-hidden="true"><i class="fa-solid fa-book"></i></span>
    `;
    card.appendChild(header);

    const row = document.createElement("div");
    row.className = "spelling-card__row";
    const wordSpan = document.createElement("span");
    wordSpan.className = "spelling-card__word";
    wordSpan.textContent = word;
    const arrowSpan = document.createElement("span");
    arrowSpan.className = "spelling-card__arrow";
    arrowSpan.textContent = "→";
    const btnsWrap = document.createElement("div");
    btnsWrap.className = "spelling-card__suggestions";

    if (topSuggestions.length === 0) {
      const none = document.createElement("span");
      none.className = "spelling-card__none";
      none.textContent = "Санал олдсонгүй.";
      btnsWrap.appendChild(none);
    } else {
      for (const s of topSuggestions) {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className =
          "spelling-card__suggestion-btn" +
          (s === selected ? " spelling-card__suggestion-btn--selected" : "");
        btn.textContent = s;
        btn.addEventListener("click", () => onCardSuggestionClick(word, topSuggestions, s));
        btnsWrap.appendChild(btn);
      }
    }
    row.appendChild(wordSpan);
    row.appendChild(arrowSpan);
    row.appendChild(btnsWrap);
    card.appendChild(row);

    const preview = document.createElement("div");
    preview.className = "spelling-card__preview";
    const previewOld = document.createElement("span");
    previewOld.className = "spelling-card__preview-old";
    previewOld.textContent = word;
    const previewNew = document.createElement("span");
    previewNew.className = "spelling-card__preview-new";
    previewNew.textContent = selected || "";
    preview.appendChild(previewOld);
    preview.appendChild(previewNew);
    card.appendChild(preview);

    const actions = document.createElement("div");
    actions.className = "spelling-card__actions";
    const acceptBtn = document.createElement("button");
    acceptBtn.type = "button";
    acceptBtn.className = "spelling-card__accept";
    acceptBtn.textContent = "Засах";
    acceptBtn.disabled = !selected;
    acceptBtn.addEventListener("click", () => applyReplace(word, selected));
    const ignoreBtn = document.createElement("span");
    ignoreBtn.className = "spelling-card__ignore";
    ignoreBtn.textContent = "Алгасах";
    ignoreBtn.setAttribute("role", "button");
    ignoreBtn.tabIndex = 0;
    ignoreBtn.addEventListener("click", () => onIgnoreWord(word));
    ignoreBtn.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        onIgnoreWord(word);
      }
    });
    actions.appendChild(acceptBtn);
    actions.appendChild(ignoreBtn);
    card.appendChild(actions);

    container.appendChild(card);
  }
}

function onIgnoreWord(word) {
  ignoredWords.add(word);
  selectedSuggestionByWord.delete(word);
  renderSuggestions(lastMisspellings);
}

function onCardSuggestionClick(word, suggestions, suggestion) {
  selectedSuggestionByWord.set(word, suggestion);
  renderSuggestions(lastMisspellings);
  Word.run(async (context) => {
    const body = context.document.body;
    const results = body.search(word, { matchWholeWord: true });
    results.load("items");
    await context.sync();
    if (results.items.length > 0) {
      results.items[0].select();
      await context.sync();
    }
  }).catch((e) => console.error("Үг рүү очиход алдаа:", e));
}

async function applyReplace(fromWord, toWord) {
  if (!toWord) return;
  try {
    setStatusIcon("loading");
    setStatus(`"${fromWord}" → "${toWord}" солиж байна...`);
    await Word.run(async (context) => {
      const body = context.document.body;
      const results = body.search(fromWord, { matchWholeWord: true });
      results.load("items");
      await context.sync();

      let lastReplaced = null;
      results.items.forEach((r) => {
        const replaced = r.insertText(toWord, Word.InsertLocation.replace);
        r.font.highlightColor = null;
        replaced.font.highlightColor = null;
        lastReplaced = replaced;
      });
      await context.sync();
      if (lastReplaced) {
        const afterRange = lastReplaced.getRange(Word.RangeLocation.after);
        afterRange.select();
        await context.sync();
      }
    });
    setStatusIcon("success");
    setStatusThenClear(`"${fromWord}" үг засагдлаа.`);
    setTimeout(() => setStatusIcon("ready"), 1500);
    lastBodyText = lastBodyText.replace(new RegExp(escapeRegex(fromWord), "g"), toWord);
    lastMisspellings.delete(fromWord);
    lastMisspellingOrder = lastMisspellingOrder.filter((w) => w !== fromWord);
    lastOccurrenceIndex.delete(fromWord);
    lastNewWords.delete(fromWord);
    selectedSuggestionByWord.delete(fromWord);
    renderSuggestions(lastMisspellings);
    setTimeout(() => run(), 0);
  } catch (e) {
    console.error("Засах үед алдаа гарлаа:", e);
    setStatus("Засах үед алдаа гарлаа.");
    setStatusIcon("error");
  }
}

function escapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

Office.onReady((info) => {
  if (info.host === Office.HostType.Word) {
    document.getElementById("run").onclick = () => {
      ignoredWords.clear();
      run();
    };
    loadDictionary();
  }
});

async function loadDictionary() {
  try {
    console.log("Толь бичиг ачаалж байна...");

    // Lazy-load hunspell-asm only when needed
    const { loadModule } = await import("hunspell-asm");

    // 1. Файлуудыг ArrayBuffer хэлбэрээр татаж авах
    const [affRes, dicRes] = await Promise.all([fetch(affUrl), fetch(dicUrl)]);

    const affBuffer = new Uint8Array(await affRes.arrayBuffer());
    const dicBuffer = new Uint8Array(await dicRes.arrayBuffer());

    // 2. Hunspell wasm module-г ачаалж, factory авах
    const factory = await loadModule();

    // 3. aff/dic файлуудыг wasm FS руу mount хийгээд spellchecker үүсгэх
    const affPath = factory.mountBuffer(affBuffer, "mn_MN.aff");
    const dicPath = factory.mountBuffer(dicBuffer, "mn_MN.dic");
    spellChecker = factory.create(affPath, dicPath);

    console.log("Монгол хэлний толь (WASM) амжилттай уншигдлаа!");
    setStatus("Алдаа шалгахад бэлэн.");
    setStatusIcon("ready");
    startAutoSpellCheck();
  } catch (error) {
    console.error("Алдаа гарлаа:", error);
    setStatus("Толь уншихад алдаа гарлаа.");
    setStatusIcon("error");
  }
}

let textCheckTimer = null;

function startAutoSpellCheck() {
  if (textCheckTimer) return;
  run();
  textCheckTimer = setInterval(async () => {
    if (!spellChecker) return;
    try {
      const currentText = await Word.run(async (context) => {
        const body = context.document.body;
        body.load("text");
        await context.sync();
        return body.text;
      });
      if (currentText !== lastBodyText) run();
    } catch (e) {
      console.error("Текст шалгахад алдаа:", e);
    }
  }, TEXT_CHECK_INTERVAL_MS);
}

export async function run() {
  setStatusIcon("loading");
  return Word.run(async (context) => {
    if (!spellChecker) {
      console.error("Толь бичиг хараахан ачаалж дуусаагүй байна.");
      setStatusIcon("error");
      return;
    }

    const body = context.document.body;
    body.load("text");
    await context.sync();

    const currentText = body.text;
    if (currentText === lastBodyText) {
      setStatusIcon("ready");
      return;
    }
    lastBodyText = currentText;
    const wordsInOrder = (currentText.match(WORD_REGEX) || []).filter((w) => w.length > 1);
    const misspellings = new Map();
    const seen = new Set();
    const occurrenceIndex = new Map();

    for (let i = 0; i < wordsInOrder.length; i++) {
      const word = wordsInOrder[i];
      if (isLatinOnly(word)) {
        seen.add(word);
        continue;
      }
      if (!seen.has(word)) {
        seen.add(word);
        const { correct, suggestions } = checkWord(word);
        if (!correct) {
          misspellings.set(word, suggestions || []);
          occurrenceIndex.set(word, i);
        }
      } else if (misspellings.has(word)) {
        occurrenceIndex.set(word, i);
      }
    }

    const prevKeys = new Set(lastMisspellings.keys());
    lastMisspellings = misspellings;
    lastOccurrenceIndex = occurrenceIndex;
    lastMisspellingOrder = [...misspellings.keys()].sort(
      (a, b) => (occurrenceIndex.get(b) ?? 0) - (occurrenceIndex.get(a) ?? 0)
    );
    lastNewWords = new Set(lastMisspellingOrder.filter((w) => !prevKeys.has(w)));
    renderSuggestions(lastMisspellings);
    console.log("Олдсон алдаанууд:", Array.from(misspellings.keys()));
    setStatusIcon("ready");
    await context.sync();
  }).catch((err) => {
    console.error("Алдаа шалгахад алдаа:", err);
    setStatusIcon("error");
  });
}
